//go:build windows

package main

import (
	"archive/zip"
	"bytes"
	"crypto/sha256"
	_ "embed"
	"encoding/hex"
	"fmt"
	"io"
	"os"
	"path/filepath"
	"strings"
)

// Generated by scripts/build-windows.sh immediately before the Windows build.
// Keeping the compressed payloads inside the controller gives users one EXE;
// they are expanded into the private application-data directory on first run.
//
//go:embed embedded/runtime.zip
var embeddedRuntime []byte

//go:embed embedded/platform-tools.zip
var embeddedPlatformTools []byte

//go:embed embedded/YourLM-Android-arm64.apk
var embeddedAPK []byte

func bundleID() string {
	h := sha256.New()
	h.Write(embeddedRuntime)
	h.Write(embeddedPlatformTools)
	h.Write(embeddedAPK)
	return hex.EncodeToString(h.Sum(nil))[:16]
}

func safeZipName(name string) (string, error) {
	name = filepath.ToSlash(name)
	clean := filepath.ToSlash(filepath.Clean(name))
	if clean == "." || strings.HasPrefix(clean, "../") || strings.HasPrefix(clean, "/") || strings.Contains(clean, ":") {
		return "", fmt.Errorf("nieprawidłowa ścieżka w komponencie: %q", name)
	}
	return filepath.FromSlash(clean), nil
}

func extractBundle(data []byte, destination string) error {
	reader, err := zip.NewReader(bytes.NewReader(data), int64(len(data)))
	if err != nil {
		return err
	}
	for _, item := range reader.File {
		name, err := safeZipName(item.Name)
		if err != nil {
			return err
		}
		path := filepath.Join(destination, name)
		if item.FileInfo().IsDir() {
			if err := os.MkdirAll(path, 0700); err != nil {
				return err
			}
			continue
		}
		if err := os.MkdirAll(filepath.Dir(path), 0700); err != nil {
			return err
		}
		in, err := item.Open()
		if err != nil {
			return err
		}
		out, err := os.OpenFile(path, os.O_WRONLY|os.O_CREATE|os.O_TRUNC, 0700)
		if err == nil {
			_, err = io.Copy(out, in)
		}
		closeOut := error(nil)
		if out != nil {
			closeOut = out.Close()
		}
		closeIn := in.Close()
		if err != nil {
			return err
		}
		if closeOut != nil {
			return closeOut
		}
		if closeIn != nil {
			return closeIn
		}
	}
	return nil
}

func atomicFile(path string, data []byte) error {
	if current, err := os.ReadFile(path); err == nil && bytes.Equal(current, data) {
		return nil
	}
	if err := os.MkdirAll(filepath.Dir(path), 0700); err != nil {
		return err
	}
	tmp := path + ".part"
	if err := os.WriteFile(tmp, data, 0600); err != nil {
		return err
	}
	_ = os.Remove(path)
	return os.Rename(tmp, path)
}

func sameFile(path string, expected []byte) bool {
	file, err := os.Open(path)
	if err != nil {
		return false
	}
	defer file.Close()
	got := sha256.New()
	if _, err := io.Copy(got, file); err != nil {
		return false
	}
	want := sha256.Sum256(expected)
	return bytes.Equal(got.Sum(nil), want[:])
}

// bundleMatches makes the completeness marker recoverable: antivirus cleanup,
// disk corruption, or an interrupted update causes a fresh private extraction.
func bundleMatches(data []byte, destination string) bool {
	reader, err := zip.NewReader(bytes.NewReader(data), int64(len(data)))
	if err != nil {
		return false
	}
	for _, item := range reader.File {
		if item.FileInfo().IsDir() {
			continue
		}
		name, err := safeZipName(item.Name)
		if err != nil {
			return false
		}
		in, err := item.Open()
		if err != nil {
			return false
		}
		expected, err := io.ReadAll(in)
		closeErr := in.Close()
		if err != nil || closeErr != nil || !sameFile(filepath.Join(destination, name), expected) {
			return false
		}
	}
	return true
}

func prepareBundledAssets(root string) (componentPaths, error) {
	if len(embeddedRuntime) == 0 || len(embeddedPlatformTools) == 0 || len(embeddedAPK) == 0 {
		return componentPaths{}, fmt.Errorf("ten build nie zawiera kompletnych komponentów")
	}
	components := filepath.Join(root, "components")
	current := filepath.Join(components, buildVersion+"-"+bundleID())
	marker := filepath.Join(current, ".complete")
	ready := false
	if value, err := os.ReadFile(marker); err == nil && string(value) == bundleID() {
		ready = bundleMatches(embeddedRuntime, filepath.Join(current, "runtime")) &&
			bundleMatches(embeddedPlatformTools, filepath.Join(current, "platform-tools")) &&
			sameFile(filepath.Join(current, "YourLM-Android-arm64.apk"), embeddedAPK)
	}
	if !ready {
		tmp := current + ".installing"
		_ = os.RemoveAll(tmp)
		if err := os.MkdirAll(filepath.Join(tmp, "runtime"), 0700); err != nil {
			return componentPaths{}, err
		}
		if err := os.MkdirAll(filepath.Join(tmp, "platform-tools"), 0700); err != nil {
			return componentPaths{}, err
		}
		if err := extractBundle(embeddedRuntime, filepath.Join(tmp, "runtime")); err != nil {
			return componentPaths{}, fmt.Errorf("rozpakowanie silnika: %w", err)
		}
		if err := extractBundle(embeddedPlatformTools, filepath.Join(tmp, "platform-tools")); err != nil {
			return componentPaths{}, fmt.Errorf("rozpakowanie ADB: %w", err)
		}
		if err := atomicFile(filepath.Join(tmp, "YourLM-Android-arm64.apk"), embeddedAPK); err != nil {
			return componentPaths{}, fmt.Errorf("zapis APK: %w", err)
		}
		if err := os.WriteFile(filepath.Join(tmp, ".complete"), []byte(bundleID()), 0600); err != nil {
			return componentPaths{}, err
		}
		_ = os.RemoveAll(current)
		if err := os.Rename(tmp, current); err != nil {
			return componentPaths{}, err
		}
	}
	server := filepath.Join(current, "runtime", "llama-server.exe")
	rpc := filepath.Join(current, "runtime", "ggml-rpc-server.exe")
	adb := filepath.Join(current, "platform-tools", "adb.exe")
	apk := filepath.Join(current, "YourLM-Android-arm64.apk")
	for _, path := range []string{server, rpc, adb, apk} {
		if info, err := os.Stat(path); err != nil || !info.Mode().IsRegular() {
			return componentPaths{}, fmt.Errorf("brak wbudowanego komponentu %s", filepath.Base(path))
		}
	}
	entries, _ := os.ReadDir(components)
	for _, entry := range entries {
		path := filepath.Join(components, entry.Name())
		if entry.IsDir() && path != current {
			_ = os.RemoveAll(path)
		}
	}
	return componentPaths{
		runtimeRoot: filepath.Join(current, "runtime"),
		adbPath:     adb,
		apkPath:     apk,
	}, nil
}
